import{z as l,x as n,o as e,c as B,q as A,j as o,D as E,d as i,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"域分解法","description":"","frontmatter":{"title":"域分解法","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/domain-decomposition-mask.md","filePath":"litho/domain-decomposition-mask.md","lastUpdated":1791413859000}'),d={name:"litho/domain-decomposition-mask.md"};function p(m,a,D,h,_,c){const t=n("Mermaid");return e(),B("div",null,[a[2]||(a[2]=A('<h1 id="域分解法" tabindex="-1">域分解法 <a class="header-anchor" href="#域分解法" aria-label="Permalink to &quot;域分解法&quot;">​</a></h1><div class="epigraph"><p>全场麦克斯韦不可算；把掩模切成重叠域，近场拼接，用严格解去伺候 OPC 真正在乎的那一圈边。</p><footer>—— 对照掩模 EMF 域分解 / 重叠近场拼接的计算光刻公开方法</footer></div><p><a href="/litho/rcwa">上一课</a>把周期结构交给模态法。缺口是逻辑版既非无限周期也不可整场 FDTD。本课钉域分解。严格近场如何变成可校准的胶模型，留给<a href="/litho/resist-model-calibration">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OPC 要的是局部空中像对碎片的灵敏度。掩模 3D 的电磁相关长度通常比设计规则短：离边几个波长外，场接近「局部环境 + 周期近似」。域分解：把版切成带重叠的窗口，每个窗口 FDTD 或 RCWA 超胞，再把近场在重叠区混合，避免缝上的假衍射。Adam–Neureuther 一类工作与后续 EDA 实现走这条工程路。</p><p><span class="marginnote">术语翻译：域分解就是把「算不动的一整块」切成许多带重叠的小窗口、分别严格求解，再在重叠处缝合的手段——像拼一幅巨幅拼图时每块多留一条公共边，靠它对齐，避免拼缝处错位出「假线」。</span></p><p>缺口是<strong>可拼的严格性</strong>，不是发明一种新麦克斯韦。把域分解当「免费全芯片 FDTD」，重叠与窗宽选错会在缝上造热点。</p><h3 id="窗宽是物理不是软件参数" tabindex="-1">窗宽是物理不是软件参数 <a class="header-anchor" href="#窗宽是物理不是软件参数" aria-label="Permalink to &quot;窗宽是物理不是软件参数&quot;">​</a></h3><p>窗必须覆盖电磁相关长度与助条邻域，否则边界条件（周期、PML）污染中心像素。窗太大则回到算力墙。这与光学 TCC 的核半径不同：一个是掩模近场，一个是投影成像。</p><p><span class="marginnote">直觉类比：窗宽像听诊器一次听的范围——太小，隔壁的「心跳」（邻近图形的近场）被假设隔断，中心听到的已是假象；太大，一次听整层楼，算力先累死。必须盖住「场还能传多远」（电磁相关长度）再略有余量。</span></p>',10)),(e(),o(s,null,{default:E(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%BA%E6%AF%8F%E4%B8%AA%E6%8E%A9%E6%A8%A1%E5%8C%BA%E5%9F%9F%E9%80%89%E7%AA%97%22%5D%20--%3E%20Q%7B%22%E7%AA%97%E5%AE%BD%E5%AE%9A%E5%A4%9A%E5%A4%A7%3F%22%7D%0A%20%20Q%20--%20%22%E5%A4%AA%E7%AA%84%22%20--%3E%20SP%5B%22%E7%AA%97%E8%BE%B9%E5%88%87%E8%BF%9B%E7%94%B5%E7%A3%81%E7%9B%B8%E5%85%B3%E5%8C%BA%22%5D%0A%20%20SP%20--%3E%20HOT%5B%22%E8%BE%B9%E7%95%8C%E6%9D%A1%E4%BB%B6%E6%B1%A1%E6%9F%93%E4%B8%AD%E5%BF%83%3A%20%E7%BC%9D%E4%B8%8A%E5%81%87%E7%83%AD%E7%82%B9%22%5D%0A%20%20Q%20--%20%22%E5%A4%AA%E5%AE%BD%22%20--%3E%20CPU%5B%22%E9%87%8D%E5%8F%A0%E8%AE%A1%E7%AE%97%E6%9A%B4%E6%B6%A8%3A%20%E6%92%9E%E7%AE%97%E5%8A%9B%E5%A2%99%22%5D%0A%20%20Q%20--%20%22%E5%88%9A%E5%A5%BD%22%20--%3E%20OK%5B%22%E7%9B%96%E4%BD%8F%E7%9B%B8%E5%85%B3%E9%95%BF%E5%BA%A6%E4%B8%8E%E5%8A%A9%E6%9D%A1%E9%82%BB%E5%9F%9F%22%5D%0A%20%20OK%20--%3E%20BAL%5B%22%E5%A4%9F%E5%87%86%E4%B8%94%E5%8F%AF%E5%B9%B6%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p><span class="marginnote">分解是空间上的；与 SMO 的光瞳分解不是一件事。不要把「decomposition」在双重图形着色课里的词义混进来——那是后课着色。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：按图形密度或规则网格切窗 → 每窗严格 EMF → 重叠加权拼接 → 远场成像或生成局部边界条件给紧凑核。热区窗加密、稀疏区用薄屏。与 GPU：窗独立，可并行，但仍不是全芯片每迭代全严格。</p><p>验证：与大窗 FDTD 参考比中心 CD；缝上 EPE 必须低于预算。</p><p><span class="marginnote">为什么重要：缝伪影若没被监测，会在模型里长出一圈「不存在的衍射」，OPC 把假热点当真、往错误方向修图形——硅上的问题没修掉，反而添了新的。每条缝的 EPE 预算与抽检大窗，是这套方法的保命绳。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>麦克斯韦是局域微分方程，信息以有限速度（数值上以网格）传播；稳态频域里是倏逝衰减长度。超过衰减长度，远处几何对本地近场的贡献可忽略，于是分解合法。金属波导般的异常结构可以让相关长度变长，窗宽经验必须覆盖这类图形，不能只按介质石英估。</p>',7)),(e(),o(s,null,{default:E(()=>[r(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHIP%5B%22%E5%85%A8%E8%8A%AF%E7%89%87%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20WIN%5B%22%E9%87%8D%E5%8F%A0%E7%AA%97%22%5D%0A%20%20WIN%20--%3E%20EMF%5B%22%E7%AA%97%E5%86%85%20FDTD%20%2F%20RCWA%22%5D%0A%20%20EMF%20--%3E%20JOIN%5B%22%E8%BF%91%E5%9C%BA%E6%8B%BC%E6%8E%A5%22%5D%0A%20%20JOIN%20--%3E%20IMG%5B%22%E6%88%90%E5%83%8F%20%2F%20%E7%B4%A7%E5%87%91%E6%A0%B8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>域分解不消除材料 \\(n,k\\) 误差，不替代 AIMS 对修复材料。缝伪影是方法风险，必须有监测。不把某 EDA 模块名当算法定义。</p><p>后课默认：严格 EMF 可以按窗提供教师数据；下一课用这些（外加晶圆 FEM）去校准紧凑胶模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>域分解用重叠窗把严格掩模 EMF 接到可算尺度。</li><li>窗宽由电磁相关长度决定；缝必须验证。</li><li>仍不能每步全芯片严格，只给紧凑核与热区当老师。</li><li>出处：掩模 EMF 域分解的计算光刻公开方法（Adam–Neureuther 传统及后续工程实现）。</li></ul>',5))])}const T=l(d,[["render",p]]);export{u as __pageData,T as default};
